import {
  EditOutlined,
  FireOutlined,
  PlusOutlined,
  ReloadOutlined,
  SearchOutlined,
  StarFilled,
  PushpinFilled,
} from '@ant-design/icons';
import { PageContainer, ProCard } from '@ant-design/pro-components';
import {
  Alert,
  App,
  Button,
  ColorPicker,
  Empty,
  Form,
  Image,
  Input,
  InputNumber,
  Modal,
  Progress,
  Segmented,
  Space,
  Tag,
  Typography,
} from 'antd';
import { TURTLE_API_BASE } from '@/api/api';
import { history, useLocation } from '@umijs/max';
import { useEffect, useMemo, useState } from 'react';
import PredictTagSidebar from '@/pages/Predict/components/PredictTagSidebar';
import {
  mktStatusLabel,
  type AdminMarket,
  type MktStatus,
} from '@/data/admin_mock_data';
import {
  fmtDate,
  fmtNum,
  getMarketStatusColor,
  MetricLine,
  mutedTextStyle,
  panelStyle,
} from '@/features/admin/shared';
import {
  useRequestMarkets,
  useRequestPredictMarketStats,
  useRequestPredictStats,
  useRequestSettlePredictMarket,
  useRequestUpdatePredictContext,
} from '@/hooks/useAdminRequest';
import type { PredictContextUpdatePayload } from '@/types/admin';
import type { PredictTagRecord } from '@/types/predictTag';

interface PredictContextFormValues {
  marketId: number;
  eventName: string;
  proText: string;
  conText: string;
  heat?: number;
  participantCount?: number;
  tags?: string;
  detail?: string;
  imageUrl?: string;
  listImage?: string;
  sideABgImage?: string;
  sideBBgImage?: string;
  sideABgColor?: string;
  sideBBgColor?: string;
}

type PredictContextMode = 'create' | 'edit';

function resolveImageUrl(url: string | undefined) {
  if (!url) {
    return '';
  }

  if (/^(https?:)?\/\//.test(url) || url.startsWith('data:')) {
    return url;
  }

  return `${TURTLE_API_BASE}${url.startsWith('/') ? '' : '/'}${url}`;
}

function hasPredictDrawLane(market: AdminMarket): boolean {
  return market.poolDraw !== undefined || Boolean(market.drawText?.trim());
}

function settleOutcomeLabel(market: AdminMarket): string {
  if (market.status !== 'SETTLED') {
    return '';
  }
  if (market.outcome === 'A') {
    return market.proText;
  }
  if (market.outcome === 'B') {
    return market.conText;
  }
  if (market.outcome === 'DRAW') {
    return market.drawText?.trim() || '平局';
  }
  return '—';
}

function ContextImageField({
  label,
  name,
  value,
}: {
  label: string;
  name: keyof PredictContextFormValues;
  value: string | undefined;
}) {
  const previewSrc = value?.trim() ? resolveImageUrl(value.trim()) : '';

  return (
    <Form.Item label={label}>
      <Space direction="vertical" size={8} style={{ width: '100%' }}>
        <Form.Item name={name} noStyle>
          <Input placeholder="相对路径或完整 URL" allowClear />
        </Form.Item>
        {previewSrc ? (
          <Image
            src={previewSrc}
            alt={`${label}预览`}
            width={104}
            height={104}
            style={{ objectFit: 'cover', borderRadius: 8 }}
          />
        ) : (
          <Typography.Text type="secondary">暂无预览</Typography.Text>
        )}
      </Space>
    </Form.Item>
  );
}

export default function PredictPage() {
  const { message } = App.useApp();
  const location = useLocation();
  const [contextForm] = Form.useForm<PredictContextFormValues>();
  const [filter, setFilter] = useState<MktStatus | 'ALL'>('ALL');
  const [search, setSearch] = useState('');
  const selectedTagSlug = useMemo(() => {
    const params = new URLSearchParams(location.search);
    return params.get('tag')?.trim() || null;
  }, [location.search]);
  const [settleModal, setSettleModal] = useState<AdminMarket | null>(null);
  const [settleChoice, setSettleChoice] = useState<'A' | 'B'>('A');
  const [settleReason, setSettleReason] = useState('');
  const [statsModal, setStatsModal] = useState<AdminMarket | null>(null);
  const [contextModal, setContextModal] = useState<AdminMarket | null>(null);
  const [contextEditorOpen, setContextEditorOpen] = useState(false);
  const [contextMode, setContextMode] = useState<PredictContextMode>('edit');
  const marketsRequest = useRequestMarkets();
  const predictStatsRequest = useRequestPredictStats();
  const marketStatsRequest = useRequestPredictMarketStats();
  const settleMarketRequest = useRequestSettlePredictMarket();
  const updatePredictContextRequest = useRequestUpdatePredictContext();
  const contextImageUrl = Form.useWatch('imageUrl', contextForm) as string | undefined;
  const contextListImage = Form.useWatch('listImage', contextForm) as string | undefined;
  const contextSideABgImage = Form.useWatch('sideABgImage', contextForm) as string | undefined;
  const contextSideBBgImage = Form.useWatch('sideBBgImage', contextForm) as string | undefined;

  const loadMarkets = async () => {
    await marketsRequest.run({
      current: 1,
      pageSize: 200,
      keyword: search,
      tagSlug: selectedTagSlug || undefined,
    });
  };

  const handleSelectTag = (tag: PredictTagRecord | string | null) => {
    if (!tag) {
      history.replace('/predict/markets');
      return;
    }

    const slug = typeof tag === 'string' ? tag : tag.slug;
    if (!slug) {
      history.replace('/predict/markets');
      return;
    }

    history.replace(`/predict/markets?tag=${encodeURIComponent(slug)}`);
  };

  const selectedTagLabel = useMemo(() => {
    if (!selectedTagSlug) {
      return '';
    }

    const matchedMarketTag = (marketsRequest.data?.data || [])
      .flatMap((market) => market.tags)
      .find((tag) => tag.toLowerCase() === selectedTagSlug.toLowerCase());

    return matchedMarketTag || selectedTagSlug;
  }, [marketsRequest.data?.data, selectedTagSlug]);

  useEffect(() => {
    void loadMarkets();
    // Market list reloads when search text or selected tag change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search, selectedTagSlug]);

  const counts = useMemo(() => {
    const next: Record<string, number> = {
      ALL: 0,
      OPEN: 0,
      CLOSED: 0,
      SETTLED: 0,
      VOIDED: 0,
    };

    for (const item of marketsRequest.data?.data || []) {
      next[item.status] = (next[item.status] || 0) + 1;
      next.ALL += 1;
    }

    if (!next.ALL && !selectedTagSlug) {
      next.ALL =
        (predictStatsRequest.data?.openCount || 0) +
        (predictStatsRequest.data?.closedCount || 0) +
        (predictStatsRequest.data?.settledCount || 0);
      next.OPEN = predictStatsRequest.data?.openCount || 0;
      next.CLOSED = predictStatsRequest.data?.closedCount || 0;
      next.SETTLED = predictStatsRequest.data?.settledCount || 0;
    }

    return next;
  }, [marketsRequest.data?.data, predictStatsRequest.data, selectedTagSlug]);

  const filtered = useMemo(() => {
    const list = marketsRequest.data?.data || [];
    if (filter === 'ALL') {
      return list;
    }

    return list.filter((item) => item.status === filter);
  }, [filter, marketsRequest.data?.data]);

  const openStatsModal = async (market: AdminMarket) => {
    setStatsModal(market);
    try {
      await marketStatsRequest.run(market.id);
    } catch (error) {
      message.error(error instanceof Error ? error.message : '盘口统计加载失败');
    }
  };

  const openSettleModal = async (market: AdminMarket) => {
    setSettleModal(market);
    setSettleChoice('A');
    setSettleReason('');
    try {
      await marketStatsRequest.run(market.id);
    } catch (error) {
      message.error(error instanceof Error ? error.message : '盘口统计加载失败');
    }
  };

  const handleSettleMarket = async () => {
    if (!settleModal) {
      return;
    }

    try {
      await settleMarketRequest.run({
        marketId: settleModal.id,
        result: settleChoice,
        remark: settleReason,
        requestId: `market-settle-${settleModal.id}-${Date.now()}`,
      });
      message.success('市场结算成功');
      setSettleModal(null);
      await Promise.all([loadMarkets(), predictStatsRequest.refresh()]);
    } catch (error) {
      message.error(error instanceof Error ? error.message : '市场结算失败');
    }
  };

  const openContextModal = (market: AdminMarket) => {
    setContextMode('edit');
    setContextModal(market);
    setContextEditorOpen(true);
    contextForm.setFieldsValue({
      marketId: market.id,
      eventName: market.title,
      proText: market.proText,
      conText: market.conText,
      heat: market.heat,
      participantCount: market.betCount,
      tags: market.tags.join(', '),
      detail: market.detail,
      imageUrl: market.imageUrl,
      listImage: market.listImage,
      sideABgImage: market.sideABgImage,
      sideBBgImage: market.sideBBgImage,
      sideABgColor: market.sideABgColor,
      sideBBgColor: market.sideBBgColor,
    });
  };

  const openCreateContextModal = () => {
    setContextMode('create');
    setContextModal(null);
    contextForm.resetFields();
    contextForm.setFieldsValue({
      proText: '',
      conText: '',
      tags: '',
      sideABgColor: '#E23D3D',
      sideBBgColor: '#276EF1',
    });
    setContextEditorOpen(true);
  };

  const handleUpdateContext = async () => {
    if (contextMode === 'edit' && !contextModal) {
      return;
    }

    try {
      const values = await contextForm.validateFields();
      const payload: PredictContextUpdatePayload = {
        marketId: contextModal?.id ?? values.marketId,
        eventName: values.eventName,
        proText: values.proText,
        conText: values.conText,
        heat: values.heat,
        participantCount: values.participantCount,
        tags: values.tags,
        detail: values.detail,
        imageUrl: values.imageUrl,
        listImage: values.listImage,
        sideABgImage: values.sideABgImage,
        sideBBgImage: values.sideBBgImage,
        sideABgColor: values.sideABgColor,
        sideBBgColor: values.sideBBgColor,
      };
      await updatePredictContextRequest.run(payload);
      message.success(contextMode === 'create' ? '预测已新增' : '市场上下文已更新');
      setContextEditorOpen(false);
      setContextModal(null);
      setContextMode('edit');
      contextForm.resetFields();
      await loadMarkets();
    } catch (error) {
      if (error instanceof Error) {
        message.error(error.message);
      }
    }
  };

  const options = [
    { label: `全部 (${counts.ALL || 0})`, value: 'ALL' },
    { label: `进行中 (${counts.OPEN || 0})`, value: 'OPEN' },
    { label: `已关闭 (${counts.CLOSED || 0})`, value: 'CLOSED' },
    { label: `已结算 (${counts.SETTLED || 0})`, value: 'SETTLED' },
    { label: `已作废 (${counts.VOIDED || 0})`, value: 'VOIDED' },
  ];

  return (
    <PageContainer title="预测市场管理">
      <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start', width: '100%' }}>
        <PredictTagSidebar
          selectedSlug={selectedTagSlug}
          onSelect={handleSelectTag}
          onTagsRefreshed={() => void loadMarkets()}
        />

        <Space direction="vertical" size={16} style={{ flex: 1, minWidth: 0 }}>
          <div className="turtle-page-toolbar">
            <Space direction="vertical" size={16} style={{ width: '100%' }}>
              {marketsRequest.error instanceof Error ? (
                <Alert
                  type="error"
                  showIcon
                  message="预测市场加载失败"
                  description={marketsRequest.error.message}
                />
              ) : null}

              <ProCard style={panelStyle}>
                <Space style={{ width: '100%', justifyContent: 'space-between' }} wrap>
                  <Input
                    allowClear
                    prefix={<SearchOutlined />}
                    placeholder="搜索市场..."
                    style={{ width: 280 }}
                    value={search}
                    onChange={(event) => setSearch(event.target.value)}
                  />
                  <Space wrap>
                    <Button type="primary" icon={<PlusOutlined />} onClick={openCreateContextModal}>
                      新增预测
                    </Button>
                    <Button
                      icon={<ReloadOutlined />}
                      loading={marketsRequest.loading}
                      onClick={() => void loadMarkets()}
                    >
                      刷新市场
                    </Button>
                  </Space>
                </Space>
              </ProCard>

              {selectedTagSlug ? (
                <Alert
                  type="info"
                  showIcon
                  message={`当前标签分类：${selectedTagLabel}`}
                  action={
                    <Button size="small" onClick={() => handleSelectTag(null)}>
                      查看全部分类
                    </Button>
                  }
                />
              ) : null}

              <Segmented
                block
                options={options}
                value={filter}
                onChange={(value) => setFilter(value as MktStatus | 'ALL')}
              />
            </Space>
          </div>

        <Space direction="vertical" size={16} style={{ width: '100%' }}>
          {!marketsRequest.loading && filtered.length === 0 ? (
            <ProCard style={panelStyle}>
              <Empty
                description={
                  selectedTagSlug
                    ? `标签「${selectedTagLabel}」下暂无市场数据`
                    : '当前筛选条件下暂无市场数据'
                }
              />
            </ProCard>
          ) : null}

          {filtered.map((market) => {
            const hasDraw = hasPredictDrawLane(market);
            const tiePool = hasDraw ? (market.poolDraw ?? 0) : 0;
            const drawLabel = market.drawText?.trim() || '平局';
            const total = hasDraw ? market.poolA + market.poolB + tiePool : market.poolA + market.poolB;
            const pctA = total ? Math.round((market.poolA / total) * 100) : hasDraw ? 34 : 50;
            const pctB = total
              ? hasDraw
                ? Math.round((market.poolB / total) * 100)
                : Math.max(0, 100 - pctA)
              : hasDraw
                ? 33
                : 50;
            const pctDraw = hasDraw && total ? Math.max(0, 100 - pctA - pctB) : 0;
            const oddsA = market.poolA > 0 && total ? (total / market.poolA).toFixed(2) : '—';
            const oddsB = market.poolB > 0 && total ? (total / market.poolB).toFixed(2) : '—';
            const oddsDraw = hasDraw && tiePool > 0 && total ? (total / tiePool).toFixed(2) : '—';

            return (
              <ProCard key={market.id} style={panelStyle}>
                <Space direction="vertical" size={14} style={{ width: '100%' }}>
                  <Space wrap>
                    <Tag color={getMarketStatusColor(market.status)}>{mktStatusLabel[market.status]}</Tag>
                    <Typography.Text style={mutedTextStyle}>#{market.id}</Typography.Text>
                    <Tag>{market.source}</Tag>
                    {market.isPinned ? <PushpinFilled style={{ color: '#1677ff' }} /> : null}
                    {market.isRecommended ? <StarFilled style={{ color: '#faad14' }} /> : null}
                  </Space>

                  <Typography.Title level={4} style={{ margin: 0 }}>
                    {market.title}
                  </Typography.Title>

                  {market.imageUrl?.trim() ? (
                    <div>
                      <Image
                        src={resolveImageUrl(market.imageUrl.trim())}
                        alt=""
                        width={120}
                        height={120}
                        style={{ objectFit: 'cover', borderRadius: 8 }}
                      />
                    </div>
                  ) : null}

                  <div>
                    {hasDraw ? (
                      <>
                        <Space
                          style={{
                            width: '100%',
                            justifyContent: 'space-between',
                            flexWrap: 'wrap',
                            rowGap: 8,
                          }}
                        >
                          <Typography.Text style={{ color: '#344054' }}>
                            正方: {market.proText} ({pctA}%)
                          </Typography.Text>
                          <Typography.Text style={{ color: '#595959' }}>
                            {drawLabel} ({pctDraw}%)
                          </Typography.Text>
                          <Typography.Text style={{ color: '#344054' }}>
                            反方: {market.conText} ({pctB}%)
                          </Typography.Text>
                        </Space>
                        <div
                          style={{
                            display: 'flex',
                            height: 10,
                            borderRadius: 6,
                            overflow: 'hidden',
                            marginTop: 8,
                            border: '1px solid rgba(0,0,0,0.06)',
                          }}
                        >
                          <div
                            style={{
                              flex: Math.max(pctA, 1),
                              background: '#1677ff',
                              minWidth: pctA ? 2 : 0,
                            }}
                          />
                          <div
                            style={{
                              flex: Math.max(pctDraw, 1),
                              background: '#8c8c8c',
                              minWidth: pctDraw ? 2 : 0,
                            }}
                          />
                          <div
                            style={{
                              flex: Math.max(pctB, 1),
                              background: '#fa8c16',
                              minWidth: pctB ? 2 : 0,
                            }}
                          />
                        </div>
                      </>
                    ) : (
                      <>
                        <Space style={{ width: '100%', justifyContent: 'space-between' }}>
                          <Typography.Text style={{ color: '#344054' }}>
                            正方: {market.proText} ({pctA}%)
                          </Typography.Text>
                          <Typography.Text style={{ color: '#344054' }}>
                            反方: {market.conText} ({pctB}%)
                          </Typography.Text>
                        </Space>
                        <Progress
                          percent={pctA}
                          showInfo={false}
                          strokeColor="#1677ff"
                          trailColor="#fa8c16"
                        />
                      </>
                    )}
                  </div>

                  <Space wrap size={[16, 8]}>
                    <MetricLine label="投注数" value={market.betCount} />
                    <MetricLine label="总金额" value={fmtNum(total)} />
                    <MetricLine label="赔率A" value={`x${oddsA}`} valueColor="#1677ff" />
                    {hasDraw ? (
                      <MetricLine
                        label={`赔率·${drawLabel}`}
                        value={`x${oddsDraw}`}
                        valueColor="#595959"
                      />
                    ) : null}
                    <MetricLine label="赔率B" value={`x${oddsB}`} valueColor="#fa8c16" />
                    {hasDraw ? (
                      <MetricLine label="平局池" value={fmtNum(tiePool)} valueColor="#595959" />
                    ) : null}
                    <MetricLine label="截止" value={fmtDate(market.closeTime)} />
                    <MetricLine
                      label="热度"
                      value={market.heat}
                      icon={<FireOutlined style={{ color: '#ff4d4f' }} />}
                    />
                  </Space>

                  <Space wrap>
                    {market.tags.map((tag) => (
                      <Tag
                        key={tag}
                        color={selectedTagSlug === tag ? 'processing' : undefined}
                        style={{ cursor: 'pointer' }}
                        onClick={() => handleSelectTag(tag)}
                      >
                        {tag}
                      </Tag>
                    ))}
                  </Space>

                  {(market.status === 'SETTLED' || market.status === 'VOIDED') && (
                    <div
                      style={{
                        padding: 12,
                        borderRadius: 12,
                        background: market.status === 'SETTLED' ? '#f6ffed' : '#fff2f0',
                      }}
                    >
                      <Space wrap>
                        <Typography.Text strong>
                          {market.status === 'SETTLED'
                            ? `结算结果: ${settleOutcomeLabel(market)}`
                            : '已作废'}
                        </Typography.Text>
                        <Typography.Text>操作人: {market.settledBy}</Typography.Text>
                        <Typography.Text>原因: {market.settleReason}</Typography.Text>
                      </Space>
                    </div>
                  )}

                  {(market.status === 'OPEN' || market.status === 'CLOSED') && (
                    <Space>
                      <Button icon={<EditOutlined />} onClick={() => openContextModal(market)}>
                        编辑上下文
                      </Button>
                      <Button onClick={() => void openStatsModal(market)}>盘口统计</Button>
                      <Button
                        type="primary"
                        onClick={() => {
                          void openSettleModal(market);
                        }}
                      >
                        结算
                      </Button>
                    </Space>
                  )}
                </Space>
              </ProCard>
            );
          })}
        </Space>
        </Space>
      </div>

      <Modal
        open={Boolean(settleModal)}
        title="人工结算"
        onCancel={() => setSettleModal(null)}
        onOk={() => void handleSettleMarket()}
        okText="确认结算"
        cancelText="取消"
        confirmLoading={settleMarketRequest.loading}
      >
        {settleModal ? (
          <Space direction="vertical" size={16} style={{ width: '100%' }}>
            <Typography.Text>{settleModal.title}</Typography.Text>
            {marketStatsRequest.data ? (
              <Alert
                type="info"
                showIcon
                message={`正方 ${marketStatsRequest.data.proAmount} / 反方 ${marketStatsRequest.data.conAmount}${
                  marketStatsRequest.data.drawAmount !== undefined
                    ? ` / ${settleModal.drawText?.trim() || '平局'} ${marketStatsRequest.data.drawAmount}`
                    : ''
                }`}
                description={`投注人数 正${marketStatsRequest.data.proUserCount} : 反${
                  marketStatsRequest.data.conUserCount
                }${
                  marketStatsRequest.data.drawUserCount !== undefined
                    ? ` : ${settleModal.drawText?.trim() || '平局'}${marketStatsRequest.data.drawUserCount}`
                    : ''
                }，总下注 ${marketStatsRequest.data.totalAmount}`}
              />
            ) : null}
            <Segmented
              block
              value={settleChoice}
              onChange={(value) => setSettleChoice(value as 'A' | 'B')}
              options={[
                { label: settleModal.proText, value: 'A' },
                { label: settleModal.conText, value: 'B' },
              ]}
            />
            <Input.TextArea
              rows={4}
              placeholder="请输入操作原因..."
              value={settleReason}
              onChange={(event) => setSettleReason(event.target.value)}
            />
          </Space>
        ) : null}
      </Modal>

      <Modal
        open={Boolean(statsModal)}
        title="盘口统计"
        onCancel={() => setStatsModal(null)}
        footer={null}
      >
        {statsModal && marketStatsRequest.data ? (
          <Space direction="vertical" size={16} style={{ width: '100%' }}>
            <Typography.Text>{statsModal.title}</Typography.Text>
            <Space wrap>
              <Tag color="processing">正方人数 {marketStatsRequest.data.proUserCount}</Tag>
              <Tag color="warning">反方人数 {marketStatsRequest.data.conUserCount}</Tag>
              {marketStatsRequest.data.drawUserCount !== undefined ? (
                <Tag>平局人数 {marketStatsRequest.data.drawUserCount}</Tag>
              ) : null}
              <Tag>总下注 {marketStatsRequest.data.totalAmount}</Tag>
              <Tag>总笔数 {marketStatsRequest.data.totalBetCount}</Tag>
            </Space>
            <Typography.Text>正方金额：{marketStatsRequest.data.proAmount}</Typography.Text>
            {marketStatsRequest.data.drawAmount !== undefined ? (
              <Typography.Text>
                {statsModal.drawText?.trim() || '平局'}金额：{marketStatsRequest.data.drawAmount}
              </Typography.Text>
            ) : null}
            <Typography.Text>反方金额：{marketStatsRequest.data.conAmount}</Typography.Text>
          </Space>
        ) : null}
      </Modal>

      <Modal
        width={760}
        open={contextEditorOpen}
        title={contextMode === 'create' ? '新增预测' : '编辑市场上下文'}
        onCancel={() => {
          setContextEditorOpen(false);
          setContextModal(null);
          setContextMode('edit');
          contextForm.resetFields();
        }}
        onOk={() => void handleUpdateContext()}
        okText={contextMode === 'create' ? '新增' : '保存'}
        cancelText="取消"
        confirmLoading={updatePredictContextRequest.loading}
        destroyOnHidden
      >
        <Form form={contextForm} layout="vertical">
          <Form.Item
            name="marketId"
            label="市场 ID"
            rules={[{ required: true, message: '请输入市场 ID' }]}
          >
            <InputNumber min={1} precision={0} disabled={contextMode === 'edit'} style={{ width: '100%' }} />
          </Form.Item>
          <Form.Item
            name="eventName"
            label="事件标题"
            rules={[{ required: true, message: '请输入事件标题' }]}
          >
            <Input />
          </Form.Item>
          <Form.Item
            name="proText"
            label="正方文案"
            rules={[{ required: true, message: '请输入正方文案' }]}
          >
            <Input />
          </Form.Item>
          <Form.Item
            name="conText"
            label="反方文案"
            rules={[{ required: true, message: '请输入反方文案' }]}
          >
            <Input />
          </Form.Item>
          <Form.Item name="tags" label="标签">
            <Input placeholder="多个标签用逗号分隔" />
          </Form.Item>
          <Form.Item name="participantCount" label="参与人数">
            <InputNumber min={0} precision={0} style={{ width: '100%' }} />
          </Form.Item>
          <Form.Item name="heat" label="热度">
            <InputNumber min={0} precision={0} style={{ width: '100%' }} />
          </Form.Item>
          <ContextImageField name="imageUrl" label="封面图链接" value={contextImageUrl} />
          <ContextImageField name="listImage" label="列表图片" value={contextListImage} />
          <Space size={16} align="start" style={{ width: '100%' }}>
            <div style={{ flex: 1 }}>
              <ContextImageField name="sideABgImage" label="正方背景图" value={contextSideABgImage} />
            </div>
            <div style={{ flex: 1 }}>
              <ContextImageField name="sideBBgImage" label="反方背景图" value={contextSideBBgImage} />
            </div>
          </Space>
          <Space size={16} style={{ width: '100%' }}>
            <Form.Item
              name="sideABgColor"
              label="正方背景色"
              getValueFromEvent={(color) => color.toHexString().toUpperCase()}
              style={{ flex: 1 }}
            >
              <ColorPicker format="hex" disabledAlpha showText />
            </Form.Item>
            <Form.Item
              name="sideBBgColor"
              label="反方背景色"
              getValueFromEvent={(color) => color.toHexString().toUpperCase()}
              style={{ flex: 1 }}
            >
              <ColorPicker format="hex" disabledAlpha showText />
            </Form.Item>
          </Space>
          <Form.Item name="detail" label="上下文说明">
            <Input.TextArea rows={4} />
          </Form.Item>
        </Form>
      </Modal>
    </PageContainer>
  );
}

