        footer={null}
        onCancel={() => {
          setDetailId(null);
        }}
        destroyOnHidden
        width={560}
      >
        {tagDetailRequest.loading ? (
          <Typography.Text type="secondary">加载中...</Typography.Text>
        ) : tagDetailRequest.data ? (
          <Descriptions column={1} bordered size="small">
