        ) : null}

        <ProCard style={panelStyle}>
          <QueryFilter<PetFilterValues>
            defaultCollapsed={false}
            initialValues={{ enabled: 'all', rarity: 'all' }}
            labelWidth="auto"
            span={6}
            onFinish={handleFilterSubmit}
