              ]}
            />
          </QueryFilter>
        </ProCard>

        <ProTable<PetDefinition>
          headerTitle="开蛋配置列表"
          style={panelStyle}
          search={false}
          options={false}
          toolBarRender={() => [
            <Button key="refresh" icon={<ReloadOutlined />} onClick={() => void loadPets()}>
              刷新
            </Button>,
          ]}
          tableAlertRender={false}
          tableAlertOptionRender={false}
          rowKey="id"
          loading={petListRequest.loading}
