                label: `${item.feature_key} · ${getLocalizedLabel(item.name)}`,
                value: item.feature_key,
              }))}
            />
          </Form.Item>
          <Form.Item
            name="params_json"
            label="能力参数 JSON"
            extra="按接口契约直接提交 { params }，启用状态请放在 params.enabled 中。"
